self.addEventListener('install', (e) => {
  e.waitUntil(caches.open('app-v1').then((c) => c.addAll(['/', '/app.js', '/offline.html'])));
});
self.addEventListener('fetch', (e) => {
  e.respondWith(
    caches.match(e.request).then((cached) => cached || fetch(e.request).catch(() => caches.match('/offline.html')))
  );
});

Pinia.ejemplo:
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';

export const useCartStore = defineStore('cart', () => {
  const items = ref([]);
  const total = computed(() => items.value.reduce((acc, i) => acc + i.price, 0));
  function add(item) { items.value.push(item); }
  return { items, total, add };
});

Redux.ejemplo:
import { createSlice, configureStore } from '@reduxjs/toolkit';

const counterSlice = createSlice({
  name: 'counter',
  initialState: { value: 0 },
  reducers: { incremented: (state) => { state.value += 1; } }
});
export const { incremented } = counterSlice.actions;
export const store = configureStore({ reducer: { counter: counterSlice.reducer } });

